#include <stdio.h>

int main() {
    int remaining[] = {5, 3, 2};
    int quantum = 2, time = 0, done = 0;
    while (done < 3) {
        for (int i = 0; i < 3; i++) {
            if (remaining[i] > 0) {
                int slice = remaining[i] < quantum ? remaining[i] : quantum;
                time += slice;
                remaining[i] -= slice;
                if (remaining[i] == 0) {
                    printf("P%d finishes at %d\n", i + 1, time);
                    done++;
                }
            }
        }
    }
    return 0;
}
